def get_report(ga_property_id, credential_id, request, use_cache=None, cache_ttl_seconds=None, request_id=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0121000" if __import__("os").path.isdir("./environment_mix/0121000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # --- Validate inputs ---
    ulid_prop_re = re.compile(r"^ga_prop_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_cred_re = re.compile(r"^ga_cred_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_req_re = re.compile(r"^ga_req_[0-9A-HJKMNP-TV-Z]{10,}$")

    if not isinstance(ga_property_id, str) or not ulid_prop_re.match(ga_property_id):
        return _err("VALIDATION_ERROR", "Invalid ga_property_id.", field="ga_property_id")
    if not isinstance(credential_id, str) or not ulid_cred_re.match(credential_id):
        return _err("VALIDATION_ERROR", "Invalid credential_id.", field="credential_id")
    if not isinstance(request, dict):
        return _err("VALIDATION_ERROR", "Invalid request payload; must be an object.", field="request")
    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.", field="use_cache")
    if cache_ttl_seconds is not None:
        if not isinstance(cache_ttl_seconds, int) or cache_ttl_seconds < 0:
            return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer >= 0.", field="cache_ttl_seconds")
    if request_id is not None:
        if not isinstance(request_id, str) or not ulid_req_re.match(request_id):
            return _err("VALIDATION_ERROR", "Invalid request_id.", field="request_id")

    # --- Load datastore ---
    props = _load("ga_properties.json")
    creds = _load("google_credentials.json")
    reqs = _load("ga_requests.json")
    keys = _load("api_keys.json")
    counters = _load("api_usage_counters.json")

    # --- Helpers ---
    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b32_ulid_like(prefix):
        # Not a strict ULID; satisfies pattern constraint and uniqueness needs locally.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        rand = "".join(secrets.choice(alphabet) for _ in range(16))
        return f"{prefix}{rand}"

    def _fingerprint(request_type, ga_prop_id, payload):
        canon = json.dumps({"t": request_type, "p": ga_prop_id, "r": payload}, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(canon.encode("utf-8")).hexdigest()

    def _log_latency_ms():
        return int((time.time() - t0) * 1000)

    def _select_api_key():
        # Ambient auth: if any active key exists, treat deployment as requiring it and select one that can serve.
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None, "no_keys_configured"  # keyless deployment
        # choose an active key that allows this property
        for k in active:
            allowed = k.get("allowed_property_ids")
            if allowed is None or allowed == [] or (isinstance(allowed, list) and ga_property_id in allowed):
                return k, None
        return None, "property_not_allowed"

    def _get_counter(api_key_id, window_type, window_start_iso):
        for c in counters:
            if c.get("api_key_id") == api_key_id and c.get("window_type") == window_type and c.get("window_start") == window_start_iso:
                return c
        return None

    def _ensure_counter(api_key_id, window_type, window_start_iso):
        c = _get_counter(api_key_id, window_type, window_start_iso)
        if c is not None:
            return c
        newc = {
            "id": _b32_ulid_like("ga_cnt_"),
            "api_key_id": api_key_id,
            "window_start": window_start_iso,
            "window_type": window_type,
            "request_count": 0,
            "report_count": 0,
            "realtime_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        counters.append(newc)
        return newc

    def _minute_window_start(dt):
        dt2 = dt.replace(second=0, microsecond=0)
        return dt2.isoformat() + "Z"

    def _day_window_start(dt):
        dt2 = dt.replace(hour=0, minute=0, second=0, microsecond=0)
        return dt2.isoformat() + "Z"

    def _append_request_log(row):
        reqs.append(row)
        _save("ga_requests.json", reqs)

    def _update_key_last_used(api_key_row):
        api_key_row["last_used_at"] = now_iso
        api_key_row["updated_at"] = now_iso
        _save("api_keys.json", keys)

    def _save_counters():
        _save("api_usage_counters.json", counters)

    def _record_usage_or_reject(api_key_row, request_type):
        # Enforce minute rate limit and daily quota.
        api_key_id = api_key_row["id"]
        min_start = _minute_window_start(now)
        day_start = _day_window_start(now)

        minc = _ensure_counter(api_key_id, "minute", min_start)
        dayc = _ensure_counter(api_key_id, "day", day_start)

        # compute would-be counts
        min_would = minc["request_count"] + 1
        day_would = dayc["request_count"] + 1

        if not isinstance(api_key_row.get("rate_limit_per_minute"), int) or api_key_row["rate_limit_per_minute"] < 1:
            return False, _err("UNAUTHORIZED", "API key is misconfigured (rate limit).")
        if not isinstance(api_key_row.get("daily_quota_requests"), int) or api_key_row["daily_quota_requests"] < 1:
            return False, _err("UNAUTHORIZED", "API key is misconfigured (daily quota).")

        if min_would > api_key_row["rate_limit_per_minute"]:
            return False, _err("RATE_LIMIT", "Rate limit exceeded.", limit=api_key_row["rate_limit_per_minute"], window="minute")
        if day_would > api_key_row["daily_quota_requests"]:
            return False, _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=api_key_row["daily_quota_requests"], window="day")

        # apply increments
        minc["request_count"] = min_would
        dayc["request_count"] = day_would
        if request_type == "report":
            minc["report_count"] += 1
            dayc["report_count"] += 1
        else:
            minc["realtime_count"] += 1
            dayc["realtime_count"] += 1
        minc["updated_at"] = now_iso
        dayc["updated_at"] = now_iso
        _save_counters()
        _update_key_last_used(api_key_row)
        return True, None

    # --- API key selection / enforcement ---
    api_key_row, key_reason = _select_api_key()
    if api_key_row is None and key_reason == "property_not_allowed":
        return _err("UNAUTHORIZED", "API key does not allow access to this property.", ga_property_id=ga_property_id)
    # If active keys exist, require usable key (ambient selection). If none exist, no enforcement.
    if api_key_row is None and key_reason != "no_keys_configured":
        return _err("UNAUTHORIZED", "No authorized API key available for this request.")

    # --- Enforce rate/quota before any "Google call" ---
    if api_key_row is not None:
        ok, err = _record_usage_or_reject(api_key_row, "report")
        if not ok:
            return err

    # --- Resolve property & credential (must exist, active, matching) ---
    prop = next((p for p in props if p.get("id") == ga_property_id), None)
    if prop is None or prop.get("status") != "active":
        # May create failed ga_requests row with PROPERTY_DISABLED_OR_MISSING
        req_id = request_id if request_id is not None else _b32_ulid_like("ga_req_")
        # idempotency: if request_id exists already, return the existing row/response
        existing = next((r for r in reqs if r.get("id") == req_id), None)
        if existing is None:
            fp = _fingerprint("report", ga_property_id, request)
            row = {
                "id": req_id,
                "request_type": "report",
                "ga_property_id": ga_property_id,
                "credential_id": credential_id,
                "status": "failed",
                "request_payload": request,
                "request_fingerprint": fp,
                "response_payload": None,
                "response_row_count": None,
                "error_code": "PROPERTY_DISABLED_OR_MISSING",
                "error_message": "Property is missing or not active.",
                "started_at": now_iso,
                "finished_at": now_iso,
                "cache_hit": False,
                "cache_expires_at": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            _append_request_log(row)
        return _err("NOT_FOUND", "GA property is missing or disabled.", error_code="PROPERTY_DISABLED_OR_MISSING", ga_property_id=ga_property_id)

    cred = next((c for c in creds if c.get("id") == credential_id), None)
    if cred is None:
        return _err("NOT_FOUND", "Credential not found.", credential_id=credential_id)
    if cred.get("ga_property_id") != ga_property_id:
        return _err("VALIDATION_ERROR", "Credential does not belong to the specified property.", field="credential_id")
    if cred.get("status") != "active":
        return _err("UNAUTHORIZED", "Credential is not active.", credential_id=credential_id)

    # --- Idempotency by request_id ---
    if request_id is not None:
        existing = next((r for r in reqs if r.get("id") == request_id), None)
        if existing is not None:
            # Return existing outcome
            return {
                "request": existing,
                "response": existing.get("response_payload"),
                "cache_hit": bool(existing.get("cache_hit")),
                "latency_ms": _log_latency_ms(),
            }

    # --- Fingerprint and caching ---
    fp = _fingerprint("report", ga_property_id, request)
    cache_allowed = True if use_cache is None else bool(use_cache)

    if cache_allowed:
        for r in reqs:
            if r.get("request_type") == "report" and r.get("request_fingerprint") == fp and r.get("status") == "succeeded":
                exp = _parse_dt(r.get("cache_expires_at"))
                if exp is not None and exp > now:
                    # Serve cached: still log a new request row with cache_hit=true
                    req_id = request_id if request_id is not None else _b32_ulid_like("ga_req_")
                    row = {
                        "id": req_id,
                        "request_type": "report",
                        "ga_property_id": ga_property_id,
                        "credential_id": credential_id,
                        "status": "succeeded",
                        "request_payload": request,
                        "request_fingerprint": fp,
                        "response_payload": r.get("response_payload"),
                        "response_row_count": r.get("response_row_count"),
                        "error_code": None,
                        "error_message": None,
                        "started_at": now_iso,
                        "finished_at": now_iso,
                        "cache_hit": True,
                        "cache_expires_at": r.get("cache_expires_at"),
                        "created_at": now_iso,
                        "updated_at": now_iso,
                    }
                    _append_request_log(row)
                    return {
                        "request": row,
                        "response": row.get("response_payload"),
                        "cache_hit": True,
                        "latency_ms": _log_latency_ms(),
                    }

    # --- Create request row (queued -> running -> succeeded/failed) ---
    req_id = request_id if request_id is not None else _b32_ulid_like("ga_req_")
    created = {
        "id": req_id,
        "request_type": "report",
        "ga_property_id": ga_property_id,
        "credential_id": credential_id,
        "status": "queued",
        "request_payload": request,
        "request_fingerprint": fp,
        "response_payload": None,
        "response_row_count": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "cache_hit": False,
        "cache_expires_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # unique(request_fingerprint) where status in ('queued','running')
    for r in reqs:
        if r.get("request_fingerprint") == fp and r.get("status") in ("queued", "running") and r.get("request_type") == "report":
            return _err("CONFLICT", "A matching request is already queued or running.", request_fingerprint=fp)

    reqs.append(created)
    _save("ga_requests.json", reqs)

    # Transition to running
    created["status"] = "running"
    created["started_at"] = now_iso
    created["updated_at"] = now_iso
    _save("ga_requests.json", reqs)

    # --- "Execute" against Google (offline deterministic response) ---
    # We cannot call Google APIs offline; generate a deterministic stub response from request+property.
    try:
        payload_canon = json.dumps(request, sort_keys=True, separators=(",", ":"))
        seed = hashlib.sha256((ga_property_id + "|" + payload_canon).encode("utf-8")).hexdigest()
        response = {
            "kind": "analyticsData#runReport",
            "property": prop.get("property_id"),
            "requestEcho": request,
            "rowCount": 0,
            "meta": {
                "simulated": True,
                "seed": seed,
            },
        }
        row_count = 0
        exec_ok = True
        exec_err_code = None
        exec_err_msg = None
    except (TypeError, ValueError) as e:
        response = None
        row_count = None
        exec_ok = False
        exec_err_code = "INVALID_REQUEST_PAYLOAD"
        exec_err_msg = str(e)

    # Finish and cache metadata
    ttl = cache_ttl_seconds
    if ttl is None:
        ttl = prop.get("default_cache_ttl_seconds")
    if not isinstance(ttl, int) or ttl < 0:
        ttl = 0

    expires_at = None
    if ttl > 0 and exec_ok:
        expires = now + datetime.timedelta(seconds=ttl)
        expires_at = expires.replace(microsecond=0).isoformat() + "Z"

    # Apply final transition running -> succeeded/failed
    if created.get("status") != "running":
        return _err("INVALID_TRANSITION", "Request is not in running state; cannot finalize.", request_id=req_id)

    created["finished_at"] = now_iso
    created["updated_at"] = now_iso
    if exec_ok:
        created["status"] = "succeeded"
        created["response_payload"] = response
        created["response_row_count"] = row_count
        created["cache_expires_at"] = expires_at
        # validate credential usage timestamp
        cred["last_validated_at"] = now_iso
        cred["updated_at"] = now_iso
        _save("google_credentials.json", creds)
    else:
        created["status"] = "failed"
        created["error_code"] = exec_err_code
        created["error_message"] = exec_err_msg
        created["response_payload"] = response
        created["response_row_count"] = row_count
        created["cache_expires_at"] = None

    _save("ga_requests.json", reqs)

    return {
        "request": created,
        "response": created.get("response_payload"),
        "cache_hit": False,
        "latency_ms": _log_latency_ms(),
    }

def get_realtime_data(ga_property_id, credential_id, request, use_cache=None, cache_ttl_seconds=None, request_id=None, **_extra):
    import json, os, datetime, time, re, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0121000" if __import__("os").path.isdir("./environment_mix/0121000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    ulid_prop_re = re.compile(r"^ga_prop_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_cred_re = re.compile(r"^ga_cred_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_req_re = re.compile(r"^ga_req_[0-9A-HJKMNP-TV-Z]{10,}$")

    if not isinstance(ga_property_id, str) or not ulid_prop_re.match(ga_property_id):
        return _err("VALIDATION_ERROR", "Invalid ga_property_id.", field="ga_property_id")
    if not isinstance(credential_id, str) or not ulid_cred_re.match(credential_id):
        return _err("VALIDATION_ERROR", "Invalid credential_id.", field="credential_id")
    if not isinstance(request, dict):
        return _err("VALIDATION_ERROR", "Invalid request payload; must be an object.", field="request")
    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.", field="use_cache")
    if cache_ttl_seconds is not None:
        if not isinstance(cache_ttl_seconds, int) or cache_ttl_seconds < 0:
            return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer >= 0.", field="cache_ttl_seconds")
    if request_id is not None:
        if not isinstance(request_id, str) or not ulid_req_re.match(request_id):
            return _err("VALIDATION_ERROR", "Invalid request_id.", field="request_id")

    props = _load("ga_properties.json")
    creds = _load("google_credentials.json")
    reqs = _load("ga_requests.json")
    keys = _load("api_keys.json")
    counters = _load("api_usage_counters.json")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b32_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        rand = "".join(secrets.choice(alphabet) for _ in range(16))
        return f"{prefix}{rand}"

    def _fingerprint(request_type, ga_prop_id, payload):
        canon = json.dumps({"t": request_type, "p": ga_prop_id, "r": payload}, sort_keys=True, separators=(",", ":"))
        import hashlib
        return hashlib.sha256(canon.encode("utf-8")).hexdigest()

    def _log_latency_ms():
        return int((time.time() - t0) * 1000)

    def _select_api_key():
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None, "no_keys_configured"
        for k in active:
            allowed = k.get("allowed_property_ids")
            if allowed is None or allowed == [] or (isinstance(allowed, list) and ga_property_id in allowed):
                return k, None
        return None, "property_not_allowed"

    def _minute_window_start(dt):
        dt2 = dt.replace(second=0, microsecond=0)
        return dt2.isoformat() + "Z"

    def _day_window_start(dt):
        dt2 = dt.replace(hour=0, minute=0, second=0, microsecond=0)
        return dt2.isoformat() + "Z"

    def _get_counter(api_key_id, window_type, window_start_iso):
        for c in counters:
            if c.get("api_key_id") == api_key_id and c.get("window_type") == window_type and c.get("window_start") == window_start_iso:
                return c
        return None

    def _ensure_counter(api_key_id, window_type, window_start_iso):
        c = _get_counter(api_key_id, window_type, window_start_iso)
        if c is not None:
            return c
        newc = {
            "id": _b32_ulid_like("ga_cnt_"),
            "api_key_id": api_key_id,
            "window_start": window_start_iso,
            "window_type": window_type,
            "request_count": 0,
            "report_count": 0,
            "realtime_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        counters.append(newc)
        return newc

    def _save_counters():
        _save("api_usage_counters.json", counters)

    def _update_key_last_used(api_key_row):
        api_key_row["last_used_at"] = now_iso
        api_key_row["updated_at"] = now_iso
        _save("api_keys.json", keys)

    def _record_usage_or_reject(api_key_row, request_type):
        api_key_id = api_key_row["id"]
        min_start = _minute_window_start(now)
        day_start = _day_window_start(now)
        minc = _ensure_counter(api_key_id, "minute", min_start)
        dayc = _ensure_counter(api_key_id, "day", day_start)

        min_would = minc["request_count"] + 1
        day_would = dayc["request_count"] + 1

        if min_would > api_key_row["rate_limit_per_minute"]:
            return False, _err("RATE_LIMIT", "Rate limit exceeded.", limit=api_key_row["rate_limit_per_minute"], window="minute")
        if day_would > api_key_row["daily_quota_requests"]:
            return False, _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=api_key_row["daily_quota_requests"], window="day")

        minc["request_count"] = min_would
        dayc["request_count"] = day_would
        minc["realtime_count"] += 1
        dayc["realtime_count"] += 1
        minc["updated_at"] = now_iso
        dayc["updated_at"] = now_iso
        _save_counters()
        _update_key_last_used(api_key_row)
        return True, None

    api_key_row, key_reason = _select_api_key()
    if api_key_row is None and key_reason == "property_not_allowed":
        return _err("UNAUTHORIZED", "API key does not allow access to this property.", ga_property_id=ga_property_id)
    if api_key_row is None and key_reason != "no_keys_configured":
        return _err("UNAUTHORIZED", "No authorized API key available for this request.")
    if api_key_row is not None:
        ok, err = _record_usage_or_reject(api_key_row, "realtime")
        if not ok:
            return err

    prop = next((p for p in props if p.get("id") == ga_property_id), None)
    if prop is None or prop.get("status") != "active":
        req_id = request_id if request_id is not None else _b32_ulid_like("ga_req_")
        existing = next((r for r in reqs if r.get("id") == req_id), None)
        if existing is None:
            fp = _fingerprint("realtime", ga_property_id, request)
            row = {
                "id": req_id,
                "request_type": "realtime",
                "ga_property_id": ga_property_id,
                "credential_id": credential_id,
                "status": "failed",
                "request_payload": request,
                "request_fingerprint": fp,
                "response_payload": None,
                "response_row_count": None,
                "error_code": "PROPERTY_DISABLED_OR_MISSING",
                "error_message": "Property is missing or not active.",
                "started_at": now_iso,
                "finished_at": now_iso,
                "cache_hit": False,
                "cache_expires_at": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            reqs.append(row)
            _save("ga_requests.json", reqs)
        return _err("NOT_FOUND", "GA property is missing or disabled.", error_code="PROPERTY_DISABLED_OR_MISSING", ga_property_id=ga_property_id)

    cred = next((c for c in creds if c.get("id") == credential_id), None)
    if cred is None:
        return _err("NOT_FOUND", "Credential not found.", credential_id=credential_id)
    if cred.get("ga_property_id") != ga_property_id:
        return _err("VALIDATION_ERROR", "Credential does not belong to the specified property.", field="credential_id")
    if cred.get("status") != "active":
        return _err("UNAUTHORIZED", "Credential is not active.", credential_id=credential_id)

    if request_id is not None:
        existing = next((r for r in reqs if r.get("id") == request_id), None)
        if existing is not None:
            return {
                "request": existing,
                "response": existing.get("response_payload"),
                "cache_hit": bool(existing.get("cache_hit")),
                "latency_ms": _log_latency_ms(),
            }

    fp = _fingerprint("realtime", ga_property_id, request)
    cache_allowed = True if use_cache is None else bool(use_cache)
    if cache_allowed:
        for r in reqs:
            if r.get("request_type") == "realtime" and r.get("request_fingerprint") == fp and r.get("status") == "succeeded":
                exp = _parse_dt(r.get("cache_expires_at"))
                if exp is not None and exp > now:
                    req_id = request_id if request_id is not None else _b32_ulid_like("ga_req_")
                    row = {
                        "id": req_id,
                        "request_type": "realtime",
                        "ga_property_id": ga_property_id,
                        "credential_id": credential_id,
                        "status": "succeeded",
                        "request_payload": request,
                        "request_fingerprint": fp,
                        "response_payload": r.get("response_payload"),
                        "response_row_count": r.get("response_row_count"),
                        "error_code": None,
                        "error_message": None,
                        "started_at": now_iso,
                        "finished_at": now_iso,
                        "cache_hit": True,
                        "cache_expires_at": r.get("cache_expires_at"),
                        "created_at": now_iso,
                        "updated_at": now_iso,
                    }
                    reqs.append(row)
                    _save("ga_requests.json", reqs)
                    return {
                        "request": row,
                        "response": row.get("response_payload"),
                        "cache_hit": True,
                        "latency_ms": _log_latency_ms(),
                    }

    req_id = request_id if request_id is not None else _b32_ulid_like("ga_req_")
    created = {
        "id": req_id,
        "request_type": "realtime",
        "ga_property_id": ga_property_id,
        "credential_id": credential_id,
        "status": "queued",
        "request_payload": request,
        "request_fingerprint": fp,
        "response_payload": None,
        "response_row_count": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "cache_hit": False,
        "cache_expires_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    for r in reqs:
        if r.get("request_fingerprint") == fp and r.get("status") in ("queued", "running") and r.get("request_type") == "realtime":
            return _err("CONFLICT", "A matching request is already queued or running.", request_fingerprint=fp)

    reqs.append(created)
    _save("ga_requests.json", reqs)

    created["status"] = "running"
    created["started_at"] = now_iso
    created["updated_at"] = now_iso
    _save("ga_requests.json", reqs)

    try:
        payload_canon = json.dumps(request, sort_keys=True, separators=(",", ":"))
        import hashlib
        seed = hashlib.sha256((ga_property_id + "|" + payload_canon).encode("utf-8")).hexdigest()
        response = {
            "kind": "analyticsData#runRealtimeReport",
            "property": prop.get("property_id"),
            "requestEcho": request,
            "rowCount": 0,
            "meta": {
                "simulated": True,
                "seed": seed,
            },
        }
        row_count = 0
        exec_ok = True
        exec_err_code = None
        exec_err_msg = None
    except (TypeError, ValueError) as e:
        response = None
        row_count = None
        exec_ok = False
        exec_err_code = "INVALID_REQUEST_PAYLOAD"
        exec_err_msg = str(e)

    ttl = cache_ttl_seconds
    if ttl is None:
        ttl = prop.get("default_cache_ttl_seconds")
    if not isinstance(ttl, int) or ttl < 0:
        ttl = 0

    expires_at = None
    if ttl > 0 and exec_ok:
        expires = now + datetime.timedelta(seconds=ttl)
        expires_at = expires.replace(microsecond=0).isoformat() + "Z"

    if created.get("status") != "running":
        return _err("INVALID_TRANSITION", "Request is not in running state; cannot finalize.", request_id=req_id)

    created["finished_at"] = now_iso
    created["updated_at"] = now_iso
    if exec_ok:
        created["status"] = "succeeded"
        created["response_payload"] = response
        created["response_row_count"] = row_count
        created["cache_expires_at"] = expires_at
        cred["last_validated_at"] = now_iso
        cred["updated_at"] = now_iso
        _save("google_credentials.json", creds)
    else:
        created["status"] = "failed"
        created["error_code"] = exec_err_code
        created["error_message"] = exec_err_msg
        created["response_payload"] = response
        created["response_row_count"] = row_count
        created["cache_expires_at"] = None

    _save("ga_requests.json", reqs)

    return {
        "request": created,
        "response": created.get("response_payload"),
        "cache_hit": False,
        "latency_ms": _log_latency_ms(),
    }

def list_ga_properties(status=None, property_id=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0121000" if __import__("os").path.isdir("./environment_mix/0121000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "deleted"):
            return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if property_id is not None and not isinstance(property_id, str):
        return _err("VALIDATION_ERROR", "property_id must be a string.", field="property_id")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "Invalid page_size; must be 1..200.", field="page_size")
    if page_token is not None and not isinstance(page_token, str):
        return _err("VALIDATION_ERROR", "page_token must be a string.", field="page_token")

    props = _load("ga_properties.json")
    keys = _load("api_keys.json")
    counters = _load("api_usage_counters.json")

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _select_api_key_for_listing():
        # Ambient auth: choose any active key; if none exist, listing is allowed without enforcement.
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        # prefer key with widest access (allowed_property_ids null/empty)
        for k in active:
            allowed = k.get("allowed_property_ids")
            if allowed is None or allowed == []:
                return k
        return active[0]

    def _minute_window_start(dt):
        dt2 = dt.replace(second=0, microsecond=0)
        return dt2.isoformat() + "Z"

    def _day_window_start(dt):
        dt2 = dt.replace(hour=0, minute=0, second=0, microsecond=0)
        return dt2.isoformat() + "Z"

    def _get_counter(api_key_id, window_type, window_start_iso):
        for c in counters:
            if c.get("api_key_id") == api_key_id and c.get("window_type") == window_type and c.get("window_start") == window_start_iso:
                return c
        return None

    def _ensure_counter(api_key_id, window_type, window_start_iso):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        def _b32(prefix):
            return prefix + "".join(secrets.choice(alphabet) for _ in range(16))
        c = _get_counter(api_key_id, window_type, window_start_iso)
        if c is not None:
            return c
        newc = {
            "id": _b32("ga_cnt_"),
            "api_key_id": api_key_id,
            "window_start": window_start_iso,
            "window_type": window_type,
            "request_count": 0,
            "report_count": 0,
            "realtime_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        counters.append(newc)
        return newc

    def _save_counters():
        _save("api_usage_counters.json", counters)

    def _update_key_last_used(api_key_row):
        api_key_row["last_used_at"] = now_iso
        api_key_row["updated_at"] = now_iso
        _save("api_keys.json", keys)

    def _record_usage_or_reject(api_key_row):
        min_start = _minute_window_start(now)
        day_start = _day_window_start(now)
        minc = _ensure_counter(api_key_row["id"], "minute", min_start)
        dayc = _ensure_counter(api_key_row["id"], "day", day_start)
        if minc["request_count"] + 1 > api_key_row["rate_limit_per_minute"]:
            return False, _err("RATE_LIMIT", "Rate limit exceeded.", limit=api_key_row["rate_limit_per_minute"], window="minute")
        if dayc["request_count"] + 1 > api_key_row["daily_quota_requests"]:
            return False, _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=api_key_row["daily_quota_requests"], window="day")
        minc["request_count"] += 1
        dayc["request_count"] += 1
        minc["updated_at"] = now_iso
        dayc["updated_at"] = now_iso
        _save_counters()
        _update_key_last_used(api_key_row)
        return True, None

    api_key_row = _select_api_key_for_listing()
    if api_key_row is not None:
        ok, err = _record_usage_or_reject(api_key_row)
        if not ok:
            return err

    # Apply key allow-list to listing visibility
    allowed_ids = None
    if api_key_row is not None:
        allowed_ids = api_key_row.get("allowed_property_ids")
        if not (allowed_ids is None or allowed_ids == [] or isinstance(allowed_ids, list)):
            allowed_ids = None

    # Decode page_token
    offset = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            tok = json.loads(raw.decode("utf-8"))
            if not isinstance(tok, dict) or "offset" not in tok or not isinstance(tok["offset"], int) or tok["offset"] < 0:
                return _err("VALIDATION_ERROR", "Invalid page_token.", field="page_token")
            offset = tok["offset"]
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "Invalid page_token.", field="page_token")

    rows = [p for p in props if isinstance(p, dict)]
    if allowed_ids is not None and allowed_ids != []:
        rows = [p for p in rows if p.get("id") in allowed_ids]
    if status is not None:
        rows = [p for p in rows if p.get("status") == status]
    if property_id is not None:
        rows = [p for p in rows if p.get("property_id") == property_id]

    # Order by created_at desc
    rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.min), reverse=True)

    total = len(rows)
    page = rows[offset: offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        tok = {"offset": next_offset}
        enc = base64.urlsafe_b64encode(json.dumps(tok, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    return {
        "data": page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "page_size": page_size,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def create_ga_property(property_id, display_name=None, time_zone=None, currency_code=None, default_cache_ttl_seconds=None, status=None, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0121000" if __import__("os").path.isdir("./environment_mix/0121000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _ensure_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj, obj["rows"]
        if isinstance(obj, list):
            return {"rows": obj}, obj
        return {"rows": []}, []

    def _now_utc():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _isoz(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        # ULID-like; good enough for local datastore uniqueness
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        out = list(reversed(out))
        rnd = random.getrandbits(80)
        for _ in range(16):
            out.append(alphabet[rnd & 31])
            rnd >>= 5
        return f"{prefix}_{''.join(out)}"

    # Validate inputs (tool schema + collection constraints)
    if not isinstance(property_id, str) or not property_id.strip():
        return _err("VALIDATION_ERROR", "property_id is required and must be a non-empty string.", field="property_id")
    property_id = property_id.strip()
    if not re.fullmatch(r"^\d+$", property_id):
        return _err("VALIDATION_ERROR", "property_id must be a numeric string.", field="property_id")

    if display_name is not None and not isinstance(display_name, str):
        return _err("VALIDATION_ERROR", "display_name must be a string.", field="display_name")
    if time_zone is not None and not isinstance(time_zone, str):
        return _err("VALIDATION_ERROR", "time_zone must be a string.", field="time_zone")

    if currency_code is not None:
        if not isinstance(currency_code, str):
            return _err("VALIDATION_ERROR", "currency_code must be a string.", field="currency_code")
        currency_code = currency_code.strip().upper()
        if not re.fullmatch(r"^[A-Z]{3}$", currency_code):
            return _err("VALIDATION_ERROR", "currency_code must match ^[A-Z]{3}$ (ISO 4217).", field="currency_code")

    if default_cache_ttl_seconds is None:
        # default per schema: field is non-null; choose a sensible default if not provided
        default_cache_ttl_seconds = 0
    if not isinstance(default_cache_ttl_seconds, int):
        return _err("VALIDATION_ERROR", "default_cache_ttl_seconds must be an integer.", field="default_cache_ttl_seconds")
    if default_cache_ttl_seconds < 0 or default_cache_ttl_seconds > 86400:
        return _err("VALIDATION_ERROR", "default_cache_ttl_seconds must be between 0 and 86400 (inclusive).", field="default_cache_ttl_seconds")

    if status is None:
        status = "active"
    if not isinstance(status, str):
        return _err("VALIDATION_ERROR", "status must be a string.", field="status")
    status = status.strip()
    if status not in ("active", "disabled"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled.", field="status")

    props_obj, props = _ensure_rows(_load("ga_properties.json"))

    # Unique(property_id) where status != 'deleted'
    existing = None
    for r in props:
        try:
            if r.get("property_id") == property_id and r.get("status") != "deleted":
                existing = r
                break
        except Exception:
            continue

    if existing is not None:
        # Realistic behavior: treat as conflict, return metadata about existing row
        return _err(
            "CONFLICT",
            "A property with this property_id already exists (non-deleted).",
            reason="ALREADY_EXISTS",
            property_id=property_id,
            existing_id=existing.get("id")
        )

    now = _now_utc()
    new_id = _gen_id("ga_prop")

    # Ensure id uniqueness
    existing_ids = set()
    for r in props:
        if isinstance(r, dict) and isinstance(r.get("id"), str):
            existing_ids.add(r["id"])
    while new_id in existing_ids:
        new_id = _gen_id("ga_prop")

    row = {
        "id": new_id,
        "property_id": property_id,
        "display_name": display_name,
        "time_zone": time_zone,
        "currency_code": currency_code,
        "status": status,
        "default_cache_ttl_seconds": default_cache_ttl_seconds,
        "created_at": _isoz(now),
        "updated_at": _isoz(now),
    }

    props.append(row)
    props_obj["rows"] = props
    _save("ga_properties.json", props_obj)

    return {"ga_property": row}

def update_ga_property(id, display_name=None, time_zone=None, currency_code=None, default_cache_ttl_seconds=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0121000" if __import__("os").path.isdir("./environment_mix/0121000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # ---- validate inputs
    if not isinstance(id, str):
        return _err("VALIDATION_ERROR", "id must be a string")
    if not re.match(r"^ga_prop_[0-9A-HJKMNP-TV-Z]{10,}$", id):
        return _err("VALIDATION_ERROR", "id does not match expected pattern")

    if display_name is not None and not isinstance(display_name, str):
        return _err("VALIDATION_ERROR", "display_name must be a string")
    if time_zone is not None and not isinstance(time_zone, str):
        return _err("VALIDATION_ERROR", "time_zone must be a string")
    if currency_code is not None:
        if not isinstance(currency_code, str):
            return _err("VALIDATION_ERROR", "currency_code must be a string")
        if not re.match(r"^[A-Z]{3}$", currency_code):
            return _err("VALIDATION_ERROR", "currency_code must match ^[A-Z]{3}$")
    if default_cache_ttl_seconds is not None:
        if not isinstance(default_cache_ttl_seconds, int):
            return _err("VALIDATION_ERROR", "default_cache_ttl_seconds must be an integer")
        if default_cache_ttl_seconds < 0 or default_cache_ttl_seconds > 86400:
            return _err("VALIDATION_ERROR", "default_cache_ttl_seconds must be between 0 and 86400")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "disabled", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")

    # ---- load and find row
    props = _load("ga_properties.json")
    row = None
    for r in props:
        if r.get("id") == id:
            row = r
            break
    if row is None:
        return _err("NOT_FOUND", "ga_properties row not found", id=id)

    # ---- apply updates with lifecycle enforcement and uniqueness
    changed = False

    # lifecycle transition check
    if status is not None and status != row.get("status"):
        cur = row.get("status")
        transitions = {
            "active": {"disabled", "deleted"},
            "disabled": {"active", "deleted"},
            "deleted": set(),
        }
        if cur not in transitions:
            return _err("CONFLICT", "Current status is invalid for lifecycle", current_status=cur)
        if status not in transitions[cur]:
            return _err("CONFLICT", "Illegal status transition", from_status=cur, to_status=status)
        row["status"] = status
        changed = True

    if display_name is not None and display_name != row.get("display_name"):
        row["display_name"] = display_name
        changed = True
    if time_zone is not None and time_zone != row.get("time_zone"):
        row["time_zone"] = time_zone
        changed = True
    if currency_code is not None and currency_code != row.get("currency_code"):
        row["currency_code"] = currency_code
        changed = True
    if default_cache_ttl_seconds is not None and default_cache_ttl_seconds != row.get("default_cache_ttl_seconds"):
        row["default_cache_ttl_seconds"] = default_cache_ttl_seconds
        changed = True

    if not changed:
        # No success without effect for mutation
        return _err("CONFLICT", "No changes to apply")

    # unique(property_id) where status != 'deleted'
    new_status = row.get("status")
    if new_status != "deleted":
        prop_id_val = row.get("property_id")
        for r in props:
            if r.get("id") != row.get("id") and r.get("status") != "deleted" and r.get("property_id") == prop_id_val:
                return _err("CONFLICT", "property_id must be unique among non-deleted properties", property_id=prop_id_val)

    row["updated_at"] = now_iso
    _save("ga_properties.json", props)

    return {"ga_property": row}

def create_google_credential(ga_property_id, credential_type, secret_ref, scopes, client_email=None, project_id=None, status=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0121000" if __import__("os").path.isdir("./environment_mix/0121000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _ulid_like(prefix):
        # Generate a sortable, ULID-ish id using time + randomness, Crockford base32 (no I,L,O,U)
        import os as _os
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(_now().timestamp() * 1000)
        # 48-bit time -> 10 chars base32 (since 32^10 ~ 2^50)
        def enc(n, length):
            out = []
            for _ in range(length):
                out.append(alphabet[n & 31])
                n >>= 5
            return "".join(reversed(out))
        time_part = enc(ts, 10)
        rand = int.from_bytes(_os.urandom(10), "big")  # 80 bits -> 16 chars base32
        rand_part = enc(rand, 16)
        return f"{prefix}{time_part}{rand_part}"

    now_iso = _now().isoformat() + "Z"

    # ---- validate
    if not isinstance(ga_property_id, str) or not re.match(r"^ga_prop_[0-9A-HJKMNP-TV-Z]{10,}$", ga_property_id):
        return _err("VALIDATION_ERROR", "ga_property_id must be a ga_prop_ ULID string")
    if not isinstance(credential_type, str):
        return _err("VALIDATION_ERROR", "credential_type must be a string")
    # Tool surface only supports "service_account", but DB enum uses "service_account_json"
    if credential_type != "service_account":
        return _err("VALIDATION_ERROR", "credential_type must be 'service_account'")
    db_credential_type = "service_account_json"

    if client_email is not None and not isinstance(client_email, str):
        return _err("VALIDATION_ERROR", "client_email must be a string")
    if project_id is not None and not isinstance(project_id, str):
        return _err("VALIDATION_ERROR", "project_id must be a string")
    if not isinstance(secret_ref, str) or not secret_ref:
        return _err("VALIDATION_ERROR", "secret_ref must be a non-empty string")
    if not isinstance(scopes, list) or len(scopes) < 1 or any((not isinstance(s, str) or not s) for s in scopes):
        return _err("VALIDATION_ERROR", "scopes must be an array of at least 1 non-empty string")

    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "rotating"):
        return _err("VALIDATION_ERROR", "status must be one of: active, rotating")

    # ---- foreign key: property must exist
    props = _load("ga_properties.json")
    if not any(p.get("id") == ga_property_id for p in props):
        return _err("NOT_FOUND", "Referenced ga_property_id not found", ga_property_id=ga_property_id)

    creds = _load("google_credentials.json")

    # unique(ga_property_id, client_email) where credential_type='service_account_json' and status != 'revoked'
    if client_email is not None:
        for c in creds:
            if (
                c.get("ga_property_id") == ga_property_id
                and c.get("credential_type") == "service_account_json"
                and c.get("status") != "revoked"
                and c.get("client_email") == client_email
            ):
                return _err("CONFLICT", "A non-revoked service account credential with this client_email already exists for the property",
                            ga_property_id=ga_property_id, client_email=client_email)

    new_row = {
        "id": _ulid_like("ga_cred_"),
        "ga_property_id": ga_property_id,
        "credential_type": db_credential_type,
        "client_email": client_email,
        "project_id": project_id,
        "secret_ref": secret_ref,
        "scopes": scopes,
        "status": status,
        "last_validated_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    creds.append(new_row)
    _save("google_credentials.json", creds)

    return {"google_credential": new_row}

def update_google_credential(id, secret_ref=None, scopes=None, status=None, last_validated_at=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0121000" if __import__("os").path.isdir("./environment_mix/0121000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _ensure_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj, obj["rows"]
        if isinstance(obj, list):
            return {"rows": obj}, obj
        return {"rows": []}, []

    def _now_utc():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _isoz(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", "last_validated_at must be a non-empty date-time string.", field="last_validated_at")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1])
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None, microsecond=0)
            return dt, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", "last_validated_at must be a valid RFC3339 date-time string.", field="last_validated_at")

    # Validate inputs (schema)
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string.", field="id")
    id = id.strip()
    if not re.fullmatch(r"^ga_cred_[0-9A-HJKMNP-TV-Z]{10,}$", id):
        return _err("VALIDATION_ERROR", "id does not match expected pattern for google_credentials.", field="id")

    if secret_ref is not None:
        if not isinstance(secret_ref, str) or not secret_ref.strip():
            return _err("VALIDATION_ERROR", "secret_ref must be a non-empty string when provided.", field="secret_ref")
        secret_ref = secret_ref.strip()

    if scopes is not None:
        if not isinstance(scopes, list) or len(scopes) < 1:
            return _err("VALIDATION_ERROR", "scopes must be an array with at least 1 item.", field="scopes")
        cleaned = []
        for i, s in enumerate(scopes):
            if not isinstance(s, str) or not s.strip():
                return _err("VALIDATION_ERROR", "scopes items must be non-empty strings.", field="scopes", index=i)
            cleaned.append(s.strip())
        scopes = cleaned

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.", field="status")
        status = status.strip()
        if status not in ("active", "rotating", "revoked"):
            return _err("VALIDATION_ERROR", "status must be one of: active, rotating, revoked.", field="status")

    parsed_lv, lv_err = _parse_dt(last_validated_at)
    if lv_err is not None:
        return lv_err

    creds_obj, creds = _ensure_rows(_load("google_credentials.json"))
    props_obj, props = _ensure_rows(_load("ga_properties.json"))

    cred = None
    for r in creds:
        if isinstance(r, dict) and r.get("id") == id:
            cred = r
            break
    if cred is None:
        return _err("NOT_FOUND", "google_credentials row not found.", id=id)

    # Enforce FK: ga_property_id must exist (if store is inconsistent, treat as NOT_FOUND)
    ga_prop_id = cred.get("ga_property_id")
    if not isinstance(ga_prop_id, str) or not ga_prop_id:
        return _err("NOT_FOUND", "Credential is missing ga_property_id reference.", id=id)
    if not any(isinstance(p, dict) and p.get("id") == ga_prop_id for p in props):
        return _err("NOT_FOUND", "Referenced ga_properties row not found for this credential.", id=id, ga_property_id=ga_prop_id)

    # Enforce lifecycle transitions: active -> rotating/revoked; rotating -> active/revoked; revoked -> []
    current_status = cred.get("status")
    allowed = {
        "active": set(["rotating", "revoked"]),
        "rotating": set(["active", "revoked"]),
        "revoked": set([]),
    }
    if not isinstance(current_status, str) or current_status not in allowed:
        return _err("VALIDATION_ERROR", "Stored credential has invalid status value.", id=id, status=current_status)

    if status is not None and status != current_status:
        if status not in allowed[current_status]:
            return _err(
                "CONFLICT",
                "Illegal status transition for google_credentials.",
                reason="INVALID_TRANSITION",
                from_status=current_status,
                to_status=status
            )

    # Apply updates
    changed = False
    if secret_ref is not None and secret_ref != cred.get("secret_ref"):
        cred["secret_ref"] = secret_ref
        changed = True
    if scopes is not None:
        # Constraint: scopes length >= 1
        if len(scopes) < 1:
            return _err("VALIDATION_ERROR", "scopes must have at least 1 item.", field="scopes")
        if scopes != cred.get("scopes"):
            cred["scopes"] = scopes
            changed = True
    if parsed_lv is not None:
        lv_str = _isoz(parsed_lv)
        if lv_str != cred.get("last_validated_at"):
            cred["last_validated_at"] = lv_str
            changed = True
    if status is not None and status != current_status:
        cred["status"] = status
        changed = True

    if not changed:
        # Idempotent: return existing resource without writing
        return {"google_credential": cred}

    cred["updated_at"] = _isoz(_now_utc())

    # Enforce uniqueness constraint:
    # unique(ga_property_id, client_email) where credential_type='service_account_json' and status!='revoked'
    if cred.get("credential_type") == "service_account_json" and cred.get("status") != "revoked":
        ce = cred.get("client_email")
        if isinstance(ce, str) and ce:
            for r in creds:
                if r is cred or not isinstance(r, dict):
                    continue
                if r.get("credential_type") == "service_account_json" and r.get("status") != "revoked":
                    if r.get("ga_property_id") == cred.get("ga_property_id") and r.get("client_email") == ce:
                        return _err(
                            "CONFLICT",
                            "A non-revoked service account credential with this client_email already exists for this property.",
                            reason="ALREADY_EXISTS",
                            ga_property_id=cred.get("ga_property_id"),
                            client_email=ce,
                            existing_id=r.get("id")
                        )

    creds_obj["rows"] = creds
    _save("google_credentials.json", creds_obj)

    return {"google_credential": cred}

def whoami(api_key=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0121000" if __import__("os").path.isdir("./environment_mix/0121000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _dt_floor_minute(dt):
        return dt.replace(second=0, microsecond=0)

    def _dt_floor_day(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        import os as _os
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(_now().timestamp() * 1000)
        def enc(n, length):
            out = []
            for _ in range(length):
                out.append(alphabet[n & 31])
                n >>= 5
            return "".join(reversed(out))
        return f"{prefix}{enc(ts,10)}{enc(int.from_bytes(_os.urandom(10),'big'),16)}"

    t0 = time.time()
    now = _now()

    keys = _load("api_keys.json")
    counters = _load("api_usage_counters.json")

    # Determine whether deployment requires API keys:
    # If there exists any api_keys row, require presenting a valid active key.
    require_key = len(keys) > 0

    key_row = None
    presented = api_key

    if presented is not None and not isinstance(presented, str):
        return _err("VALIDATION_ERROR", "api_key must be a string")

    if require_key:
        if not presented:
            return _err("UNAUTHORIZED", "API key required")
        # Authenticate by matching the presented value to key_hash OR id (client-visible id allowed)
        # Never compare against unknown plaintext behind a stored hash.
        presented_hash = hashlib.sha256(presented.encode("utf-8")).hexdigest()
        for k in keys:
            if k.get("status") == "active" and (k.get("key_hash") == presented or k.get("key_hash") == presented_hash or k.get("id") == presented):
                key_row = k
                break
        if key_row is None:
            return _err("UNAUTHORIZED", "Invalid or inactive API key")
    else:
        # If not required, still resolve if provided for showing limits/usage.
        if presented:
            presented_hash = hashlib.sha256(presented.encode("utf-8")).hexdigest()
            for k in keys:
                if k.get("status") == "active" and (k.get("key_hash") == presented or k.get("key_hash") == presented_hash or k.get("id") == presented):
                    key_row = k
                    break
            if key_row is None:
                return _err("UNAUTHORIZED", "Invalid or inactive API key")

    # Build usage snapshot if key present
    usage = None
    if key_row is not None:
        minute_start = _dt_floor_minute(now)
        day_start = _dt_floor_day(now)

        minute_counter = None
        day_counter = None
        for c in counters:
            if c.get("api_key_id") == key_row.get("id") and c.get("window_type") == "minute" and c.get("window_start") == _iso(minute_start):
                minute_counter = c
            if c.get("api_key_id") == key_row.get("id") and c.get("window_type") == "day" and c.get("window_start") == _iso(day_start):
                day_counter = c

        usage = {
            "rate_limit_per_minute": key_row.get("rate_limit_per_minute"),
            "daily_quota_requests": key_row.get("daily_quota_requests"),
            "minute_window": {
                "window_start": _iso(minute_start),
                "request_count": (minute_counter.get("request_count") if minute_counter else 0),
                "remaining": max(0, int(key_row.get("rate_limit_per_minute") or 0) - int((minute_counter.get("request_count") if minute_counter else 0))),
            },
            "day_window": {
                "window_start": _iso(day_start),
                "request_count": (day_counter.get("request_count") if day_counter else 0),
                "remaining": max(0, int(key_row.get("daily_quota_requests") or 0) - int((day_counter.get("request_count") if day_counter else 0))),
            },
            "allowed_property_ids": key_row.get("allowed_property_ids"),
            "api_key": {
                "id": key_row.get("id"),
                "key_prefix": key_row.get("key_prefix"),
                "label": key_row.get("label"),
                "status": key_row.get("status"),
                "last_used_at": key_row.get("last_used_at"),
                "created_at": key_row.get("created_at"),
                "updated_at": key_row.get("updated_at"),
            },
        }

    identity = {
        "authenticated": True,
        "api_key_required": require_key,
        "api_key_present": (key_row is not None),
        "entitlements": {
            "can_call_report": True,
            "can_call_realtime": True,
        },
        "server_time": _iso(now),
    }
    if usage is not None:
        identity["usage"] = usage

    # whoami is a read; still record dynamics if the service has request logging.
    # This schema logs GA requests only; whoami is not a GA request, so no ga_requests row is created.
    # (No other audit collection exists in schema.)

    # Update last_used_at when a key is successfully used
    if key_row is not None:
        key_row["last_used_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("api_keys.json", keys)

    return {"identity": identity}
